        "html": "\n      <footer class=\"nx nx-footer nx-sage\">\n        <div class=\"container py-5\">\n          <div class=\"row g-4\">\n            <div class=\"col-md-6 col-lg-3\">\n              <a class=\"nx-brand\" href=\"#footer-media\">Alma</a>\n              <p class=\"muted\">Centro de estética en Belgrano. Tratamientos faciales, corporales y láser.</p>\n            </div>\n            <div class=\"col-6 col-lg-3\">\n              <h2 class=\"h6\">Explorá</h2>\n              <ul class=\"foot-links\">\n                <li><a href=\"#footer-media\">Inicio</a></li>\n                <li><a href=\"#footer-media\">Tratamientos</a></li>\n                <li><a href=\"#footer-media\">Profesionales</a></li>\n                <li><a href=\"#footer-media\">Contacto</a></li>\n              </ul>\n            </div>\n            <div class=\"col-6 col-lg-3\">\n              <h2 class=\"h6\">Reservas</h2>\n              <p class=\"mb-2\"><a href=\"mailto:hola@example.com\">hola@example.com</a></p>\n              <a class=\"btn-nx btn-sm\" href=\"mailto:hola@example.com\">Reservar turno <i class=\"bi bi-arrow-right\"></i></a>\n              <p class=\"nx-note\">Datos de ejemplo.</p>\n            </div>\n            <div class=\"col-md-6 col-lg-3\">\n              <h2 class=\"h6\">Seguinos</h2>\n              <div class=\"nx-socials mb-2\">\n                <a href=\"https://instagram.com\" target=\"_blank\" rel=\"noopener\" aria-label=\"Instagram\"><i class=\"bi bi-instagram\"></i></a>\n                <a href=\"https://tiktok.com\" target=\"_blank\" rel=\"noopener\" aria-label=\"TikTok\"><i class=\"bi bi-tiktok\"></i></a>\n              </div>\n              <p class=\"muted mb-0\">Tips de cuidado y promos del mes.</p>\n            </div>\n          </div>\n          <hr class=\"nx-rule\">\n          <div class=\"d-flex flex-wrap justify-content-between gap-2 small\">\n            <span>© 2026 Alma Estética</span>\n            <span><a href=\"#footer-media\">Privacidad</a> · <a href=\"#footer-media\">Términos</a></span>\n          </div>\n        </div>\n      </footer>\n    ",
